function cohortTier(exam){if(exam.takers==null)return {key:'unknown',label:'Cohort size unavailable',note:'Cohort size was not available, so interpret item statistics cautiously.'};if(exam.takers<state.settings.cohortLow)return {key:'limited',label:'Limited evidence',note:`Only ${exam.takers} students are represented. Item statistics are unstable at this cohort size; use the signals below as prompts, not action recommendations.`};if(exam.takers<state.settings.cohortStrong)return {key:'preliminary',label:'Preliminary evidence',note:`Based on ${exam.takers} students. Recommendations are preliminary and should be confirmed with content review and future administrations.`};return {key:'standard',label:'Stronger evidence',note:`Based on ${exam.takers} students.`};}
